def test_geoip_existing_lock_readonly_and_busy_fail_open_match_generate(web,logged_in,readers):
    from core.state import file_lock
    web.geoip_store.upload('country.mmdb',io.BytesIO(b'SYNTHETIC:SG'))
    before=web.geoip_store.lock.stat()
    values=fields(geo='literal-ip',batch='Opaque|'+LINK.replace('example.com','8.8.8.8'))
    response=post(logged_in,ROUTE,body(values));assert response.status_code==200
    assert '🇸🇬 Opaque' in response.json['diff']
    assert web.geoip_store.lock.stat()==before
    with file_lock(web.geoip_store.lock,blocking=False):
        preview=post(logged_in,ROUTE,body(values));assert preview.status_code==200
        post(logged_in,'/process',body(values))
        with logged_in.session_transaction() as session:name=session['page_context']['output_filename']
        assert apply_diff(SOURCE,preview.json['diff']).encode()==Path(web.DIR_OUTPUTS,name).read_bytes()
        assert '🌐 Opaque' in preview.json['diff']


@pytest.mark.parametrize('kind',['fifo','symlink','directory'])
def test_geoip_unsafe_lock_preview_fail_open_no_repair(web,logged_in,readers,kind):
    web.geoip_store.upload('country.mmdb',io.BytesIO(b'SYNTHETIC:SG'));path=web.geoip_store.lock
    path.unlink()
    if kind=='fifo':os.mkfifo(path,0o600)
    elif kind=='symlink':path.symlink_to(web.geoip_store.settings)
    else:path.mkdir(mode=0o700)
    before=path.lstat()
    response=post(logged_in,ROUTE,body(fields(geo='literal-ip',batch='Opaque|'+LINK.replace('example.com','8.8.8.8'))))
    assert response.status_code==200 and '🌐 Opaque' in response.json['diff']
    assert path.lstat()==before


def test_source_budget_exact_utf8_and_invalid_encoding(monkeypatch):
    text='Ω\n'
    monkeypatch.setattr(yaml_diff,'MAX_YAML_BYTES',len(text.encode()))
    assert yaml_diff.read_source(io.BytesIO(text.encode()))==text
    with pytest.raises(yaml_diff.PreviewLimitError):yaml_diff.read_source(io.BytesIO((text+'x').encode()))
    with pytest.raises(yaml_diff.PreviewValidationError):yaml_diff.read_source(io.BytesIO(b'\xff'))


def test_multipart_private_spool_closed_after_preview(web,logged_in,monkeypatch):
    original=yaml_diff.read_source;seen=[]
    def inspect(stream):
        assert stream._rolled # Werkzeug uses a private spool for a >512 KiB part.
        seen.append((stream,os.fstat(stream.fileno()).st_mode & 0o777))
        return original(stream)
    monkeypatch.setattr(yaml_diff,'read_source',inspect)
    response=post(logged_in,ROUTE,body(fields(),'#'+'W'*(600*1024)+'\n'+SOURCE))
    assert response.status_code==400 and response.json['error']==yaml_diff.TOO_LARGE
    assert len(seen)==1 and seen[0][1]==0o600 and seen[0][0].closed
    assert not list(Path(web.DIR_UPLOADS).iterdir()) and not list(Path(web.DIR_OUTPUTS).iterdir())


def test_corrupt_auth_fails_closed_private_json_without_rewriting(web,logged_in):
    csrf=token(logged_in)
    path=Path(web.DIR_STATE,'auth.json');path.write_bytes(b'PRIVATE auth corrupt')
    response=logged_in.post(ROUTE,data={**fields(), 'csrf_token':csrf})
    assert response.status_code==503 and response.json['ok'] is False
    assert response.headers['Cache-Control']=='no-store' and 'PRIVATE' not in response.text
    assert path.read_bytes()==b'PRIVATE auth corrupt'


@pytest.mark.parametrize('source',[
    'x-one: &PRIVATE_ANCHOR first\nx-two: &PRIVATE_ANCHOR second\n'+SOURCE,
    '%YAML 1.1\n---\nx-float: 1e3\n'+SOURCE,
])
def test_nonfatal_yaml_warnings_private_and_generate_bytes_unchanged(web,logged_in,source,caplog,capsys):
    import warnings
    values=fields()
    with warnings.catch_warnings(record=True) as records:
        warnings.simplefilter('always')
        preview=post(logged_in,ROUTE,body(values,source))
    assert preview.status_code==200 and not records
    output=capsys.readouterr()
    assert 'PRIVATE_ANCHOR' not in output.out+output.err+caplog.text
    with warnings.catch_warnings(record=True) as original_records:
        warnings.simplefilter('always')
        generated=post(logged_in,'/process',body(values,source))
    assert generated.status_code==302 and original_records # No global warning suppression.
    with logged_in.session_transaction() as session:name=session['page_context']['output_filename']
    assert apply_diff(source,preview.json['diff']).encode()==Path(web.DIR_OUTPUTS,name).read_bytes()


def test_private_parser_does_not_change_dependency_constructor_or_warning_filters():
    import warnings
    original=yaml_utils.get_yaml_engine().constructor.yaml_constructors['tag:yaml.org,2002:float']
    filters=warnings.filters[:]
    engine=yaml_diff.private_yaml_engine()
    assert engine.constructor.yaml_constructors['tag:yaml.org,2002:float'] is not original
    assert yaml_utils.get_yaml_engine().constructor.yaml_constructors['tag:yaml.org,2002:float'] is original
    assert warnings.filters==filters
